// A dependency. It first does a benign gated op (stamping the CPED slot to this
// package), then schedules a DETACHED, frame-less privileged op: setTimeout with
// a bound native function (Deno.env.get) as the callback. When the timer fires,
// the JS stack holds only the runtime timer handler -- no evil-dep frame -- so
// stack attribution alone would see "no-user". The CPED slot must carry
// evil-dep so precedence row 2 attributes the detached op to the scheduler.
export function leak() {
  Deno.env.get("HOME");
  setTimeout(Deno.env.get.bind(null, "SECRET"), 0);
}
